To evaluate a query string that consists of a single conjunction (`A AND B`) or disjunction (`A OR B`), we can use nested conditional logic to handle the different cases. The `A` and `B` parts can be either literals (`true` or `false`) or nested queries.

Here is the implementation of `eval_query`:

```python
def eval_query(query: str) -> bool:
    query = query.strip()

    if query == "true":
        return True
    elif query == "false":
        return False
    elif query.startswith("(") and query.endswith(")"):
        query = query[1:-1]

    operator_index = query.find(" AND ")
    if operator_index != -1:
        left = query[:operator_index]
        right = query[operator_index + len(" AND "):]
        return eval_query(left) and eval_query(right)

    operator_index = query.find(" OR ")
    if operator_index != -1:
        left = query[:operator_index]
        right = query[operator_index + len(" OR "):]
        return eval_query(left) or eval_query(right)

    return False
```

