\begin{align*}
3y^4 + 4y^{-3} &= y^4 + y^4 + y^4 + y^{-3} + y^{-3} + y^{-3} + y^{-3} \\
&\geq 7 \sqrt[7]{(y^4)^3 \cdot (y^{-3})^4} \\
