```python
import os

def concatenate_filenames(filenames):
    filenames_dict = {}
    for filename in filenames:
        filename_extension = os.path.splitext(filename)[-1]
        if filename not in filenames_dict:
            filenames_dict[filename] = filename_extension
        else:
            continue
    concatenated_filenames = "_".join(filenames_dict)
    return concatenated_filenames
