Here is the implementation of `ip2int(ip_address)`:

```python
import struct

def ip2int(ip_address):
    components = ip_address.split('.')
    if len(components) != 4:
        raise ValueError('Invalid IPv4 address')
    result = 0
    for i, component in enumerate(components):
        component_int = int(component)
        if not (0 <= component_int <= 255):
            raise ValueError('Invalid IPv4 address')
        result += component_int << (24 - 8 * i)
    return struct.pack('>I', result)
```

