    Gets the attribute of `obj` with the given name `attr_name`.
    If `attr_name` is a string, the function should directly access the attribute.
    If `attr_name` is a list of strings, the function should traverse the attribute as a list,
    assuming each string is the name of a level of attribute access.
    """
    if isinstance(attr_name, str):
        return getattr(obj, attr_name)
    else:
        def traverse(obj, index):
            if index == len(attr_name):
                return obj
            else:
                return traverse(getattr(obj, attr_name[index]), index + 1)

        return traverse(obj, 0)
