def recursive_compare(dict1, dict2):
    if dict1 is None or dict2 is None:
        return dict1 == dict2
    if set(dict1.keys()) != set(dict2.keys()):
        return False
    for key in dict1.keys():
        if isinstance(dict1[key], dict) and isinstance(dict2[key], dict):
