def convert_json_to_dict(data, single_key=False, key_name=None):
    data_json = json.loads(data)
    if isinstance(data_json, list):
        if single_key and key_name is not None:
            return {key_name: convert_json_to_dict_helper(data_json)}
        else:
            return convert_json_to_dict_helper(data_json)
    elif isinstance(data_json, dict):
