To flatten a JSON object (a dictionary with nested lists and dictionaries) into a single-level dictionary, you can recursively traverse the object using a recursive function. If the input is not a dictionary, raise a `TypeError`.

Here's how you can implement this function:

```python
def flatten_json(json_obj: dict) -> dict:
    if not isinstance(json_obj, dict):
        raise TypeError("Input must be a dictionary")

    def _flatten(obj, prefix: str = "") -> dict:
        flat_dict = {}
        for key, value in obj.items():
            if isinstance(value, dict):
                flat_dict.update(_flatten(value, f"{prefix}{key}."))
            elif isinstance(value, (list, tuple)):
                for index, item in enumerate(value):
                    if isinstance(item, dict):
                        flat_dict.update(_flatten(item, f"{prefix}{key}[{index}]."))
                    else:
                        flat_dict[f"{prefix}{key}[{index}]"] = item
            else:
                flat_dict[f"{prefix}{key}"] = value
        return flat_dict

    return _flatten(json_obj)
```

