def format_and_merge_records(records, line_limit):
    formatted_records = []
    for record in records:
        formatted_record = f"{record['title']} by {record['author']} (£{record['price']:.2f})"
        formatted_records.append(formatted_record)

    merged_records = "\n".join(formatted_records)
    lines = merged_records.split("\n")

    formatted_lines = []
