def parse_byte_string(byte_string, byte_order, endian_mode):
    bytes_list = list(byte_string)
    if endian_mode == 0:
        bits_order = range(0, 8)
    else:
        bits_order = range(7, -1, -1)

    total_ones = 0

    for byte in bytes_list[byte_order:]:
        byte_binary = bin(byte)[2:].zfill(8)

        for bit_index in bits_order:
            if byte_binary[bit_index] == '1':
                total_ones += 1

    return total_ones
```

