class InvalidMatrixError(Exception):
    pass

def matrix_to_list(matrix):
    if not isinstance(matrix, list):
        raise InvalidMatrixError("Matrix must be a list of lists.")
    for row in matrix:
        if not isinstance(row, list):
            raise InvalidMatrixError("Each row must be a list.")
        if len(row) != len(matrix[0]):
            raise InvalidMatrixError("All rows must have the same length.")
    def flatten(matrix):
        result = []
        for row in matrix:
            if isinstance(row, list):
                result.extend(flatten(row))
            else:
                result.append(row)
        return result
    return flatten(matrix)
