import re

class Form:
    def __init__(self, template):
        self.template = template
        self.message_handler = None  # Add a message handler function
        self.session = {}  # Add a session dictionary

    def compile(self):
        message_pattern = re.compile(r'\{\{\s*(.*?)\s*\}\}')
        messages = message_pattern.findall(self.template)
        def replace_message(match):
            key = match.group(1)
            if key in self.session:
                return str(self.session[key])
            elif self.message_handler:
                return self.message_handler(key)
            else:
                return match.group(0)
        compiled_template = message_pattern.sub(replace_message, self.template)
        return compiled_template
