```python
def merge_sort(objects, comparator):
    if len(objects) <= 1:
        return objects
    mid = len(objects) // 2
    left = objects[:mid]
    right = objects[mid:]
    left_sorted = merge_sort(left, comparator)
    right_sorted = merge_sort(right, comparator)
    return merge(left_sorted, right_sorted, comparator)


def merge(left, right, comparator):
    result = []
    i, j = 0, 0
    while i < len(left) and j < len(right):
        if comparator(left[i], right[j]):
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result += left[i:]
    result += right[j:]
    return result


def sort_objects(objects, comparator):
    return merge_sort(objects, comparator)
```

