In Python, the Abstract Syntax Tree (AST) is a data structure that represents the syntactic structure of the source code. To make changes to the AST, you can use the `ast` module and its `NodeVisitor` class.

Here's how you could implement this function:

```python
import ast

class FunctionReplacer(ast.NodeVisitor):
    def __init__(self, func, func_new):
        self.func = func
        self.func_new = func_new

    def visit_Module(self, node):
        self.generic_visit(node)
        return node

    def visit_Call(self, node):
        self.generic_visit(node)
        if isinstance(node.func, ast.Name) and node.func.id == self.func:
            node.func.id = self.func_new
        return node

    def visit_BinOp(self, node):
        self.generic_visit(node)
        if isinstance(node.left, ast.Name) and node.left.id == self.func:
            node.left.id = self.func_new
        if isinstance(node.right, ast.Name) and node.right.id == self.func:
            node.right.id = self.func_new
        return node

    def visit_Constant(self, node):
        self.generic_visit(node)
        if isinstance(node.value, str) and node.value == self.func:
            node.value = self.func_new
        return node

def replace_function(func, func_new, ast_node):
    replacer = FunctionReplacer(func, func_new)
    return replacer.visit(ast_node)
```

