import ast

def build_id(func_name, args, kwargs):
    call_expr = ast.parse(f"{func_name}({', '.join(args)}, {', '.join(f'{k}={v}' for k, v in kwargs.items())})").body[0]
    call_node = ast.Call(
        func=ast.Name(id=func_name, ctx=ast.Load()),
        args=[ast.Constant(value=arg) for arg in args],
        keywords=[ast.keyword(arg=ast.Constant(value=key), value=ast.Constant(value=value)) for key, value in kwargs.items()]
    )
    def traverse_node(node):
        if isinstance(node, ast.Name):
            return node.id
        elif isinstance(node, ast.Str):
            return f'"{node.s}"'
        elif isinstance(node, ast.Call):
            args = ', '.join(traverse_node(arg) for arg in node.args)
            keywords = ', '.join(f'{key}={value}' for key, value in zip([n.arg for n in node.keywords], [traverse_node(n.value) for n in node.keywords]))
            return f'{node.func.id}({args}, {keywords})'
        else:
            return ''

    return traverse_node(call_node)
```

This implementation uses the `ast` module to parse the function call expression and create an `ast.Call` node representing the function call. Then, it traverses the `ast.Call` node to generate the identifier string, handling different node types such as `ast.Name`, `ast.Str`, and `ast.Call`.

