    @wraps(f)
    def wrapper(*args, **kwargs):
        outer_kwargs = kwargs.copy()
        inner_kwargs = kwargs.copy()
        for key, value in inner_kwargs.items():
            if key in outer_kwargs:
                del outer_kwargs[key]
