```python
import os
import shutil

def move_files_to_subfolders(folder_path, overwrite=False):
    if not os.path.isdir(folder_path):
        raise ValueError("The given folder path is not a directory.")
    if not isinstance(overwrite, bool):
        raise ValueError("The 'overwrite' argument should be a boolean value.")
    failed_files = []
    for file_name in os.listdir(folder_path):
        file_path = os.path.join(folder_path, file_name)
        extension = os.path.splitext(file_name)[1]
        subfolder_path = os.path.join(folder_path, extension)
        if not os.path.isdir(subfolder_path):
            os.makedirs(subfolder_path)
        if overwrite or not os.path.isfile(os.path.join(subfolder_path, file_name)):
            try:
                shutil.move(file_path, subfolder_path)
            except Exception as e:
                failed_files.append((file_path, str(e)))
    return failed_files
```

