def compress(input_string):
    output_string = ''
    current_char = ''
    current_count = 0

    for char in input_string:
        if char == current_char:
            current_count += 1
        else:
            if current_count > 1:
                output_string += current_char + str(current_count)
            else:
                output_string += current_char
            current_char = char
            current_count = 1

    if current_count > 1:
