import re

def create_regex(pattern):
    if not pattern:
        return
    elif "{" in pattern:
        group, repetition = pattern.split("{")
        return re.compile(re.escape(group) + "{" + create_regex(re.escape(repetition)) + "}")
    else:
        for symbol in ["*", "+", "?"]:
            if symbol in pattern:
                return re.compile(re.escape(pattern.split(symbol)[0]) + symbol)
