The following Python code implements the `n_queens` function using a recursive solution:

```python
def is_valid_placement(board, row, col):
    for i in range(row):
        if board[i] == col or abs(i - row) == abs(board[i] - col):
            return False
    return True

def n_queens_helper(board, row, n, solutions):
    if row == n:
        solutions.append(board[:])
        return
    for col in range(n):
        if is_valid_placement(board, row, col):
            board[row] = col
            n_queens_helper(board, row + 1, n, solutions)

def n_queens(n):
    solutions = []
    board = [-1] * n
    n_queens_helper(board, 0, n, solutions)
    return solutions
```

